import { useState, useMemo } from 'react'
import { calcStructReport, calcRebarDetail, SR_BARS } from '../engines/structReport'
import UnitInput from '../components/shared/UnitInput'
import ResultBox from '../components/shared/ResultBox'

export default function StructuralReport() {
  const [h,      setH]      = useState('200')
  const [fy,     setFy]     = useState('400')
  const [area,   setArea]   = useState('100')
  const [pRebar, setPRebar] = useState('1000')
  const [pConc,  setPConc]  = useState('150')
  const [sel,    setSel]    = useState({ name: 'D13', mode: 'Single' })

  const report = useMemo(() =>
    calcStructReport({
      h:      parseFloat(h)      || 0,
      fy:     parseFloat(fy)     || 0,
      area:   parseFloat(area)   || 0,
      pRebar: parseFloat(pRebar) || 0,
      pConc:  parseFloat(pConc)  || 0,
    }), [h, fy, area, pRebar, pConc]
  )

  const selRow = report?.schedule.find(r => r.name === sel.name)
  const detail = selRow
    ? calcRebarDetail(sel.name, sel.mode === 'Single' ? selRow.s_single : selRow.s_double,
        sel.mode, parseFloat(area) || 0, parseFloat(pRebar) || 0)
    : null

  return (
    <div>
      <h3 style={titleStyle}>RC COST — Slab Reinforcement Schedule</h3>
      <p style={descStyle}>KDS 14 20 50 : 4.6.2</p>

      {/* All inputs in one row */}
      <div className="grid md:grid-cols-5 gap-4 mb-6">
        <UnitInput id="sr-h"  label="Slab Thickness h" unit="mm"  value={h}    onChange={setH} />
        <UnitInput id="sr-fy" label="Steel Yield fy"    unit="MPa" value={fy}   onChange={setFy} />
        <UnitInput id="sr-a"  label="Construction Area" unit="m²"  value={area} onChange={setArea} />
        <div>
          <label style={labelStyle}>Rebar Unit Price (₩/kg)</label>
          <input type="number" value={pRebar} onChange={e => setPRebar(e.target.value)} style={inputStyle} />
        </div>
        <div>
          <label style={labelStyle}>Concrete Unit Price (₩/m³)</label>
          <input type="number" value={pConc} onChange={e => setPConc(e.target.value)} style={inputStyle} />
        </div>
      </div>

      {report && (
        <>
          <ResultBox title="ρ (Minimum Reinforcement Ratio) Calculation" accent>
            <p style={{ fontSize: 12, color: 'var(--tx-secondary)', marginBottom: 4 }}>{report.rho_logic}</p>
            <p style={{ fontSize: 13 }}>As,req = <b style={{ color: 'var(--val-pos)' }}>{report.as_req.toFixed(1)} mm²/m</b></p>
            <p style={{ fontSize: 13 }}>s,max = <b style={{ color: 'var(--ac-main)' }}>{report.s_max} mm</b></p>
          </ResultBox>

          <h4 style={{ fontSize: 13, fontWeight: 700, color: 'var(--ac-main)', marginTop: 20, marginBottom: 10 }}>
            Reinforcement Schedule (click to select)
          </h4>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr>
                  {['Bar', 'Area (mm²)', 'Single Spacing (mm)', 'Double Spacing (mm)'].map(h => (
                    <th key={h} style={th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {report.schedule.map(row => (
                  <tr key={row.name}>
                    <td style={{ ...td, fontWeight: 700, color: 'var(--ac-main)' }}>{row.name}</td>
                    <td style={td}>{row.area_mm2}</td>
                    <td style={{
                      ...td, cursor: 'pointer', color: 'var(--val-pos)', fontWeight: 700,
                      background: sel.name === row.name && sel.mode === 'Single' ? 'var(--bg-active)' : 'transparent',
                    }} onClick={() => setSel({ name: row.name, mode: 'Single' })}>
                      @{row.s_single} mm
                    </td>
                    <td style={{
                      ...td, cursor: 'pointer', color: 'var(--val-pos)', fontWeight: 700,
                      background: sel.name === row.name && sel.mode === 'Double' ? 'var(--bg-active)' : 'transparent',
                    }} onClick={() => setSel({ name: row.name, mode: 'Double' })}>
                      @{row.s_double} mm
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {detail && (
            <ResultBox title={`${sel.name} ${sel.mode} — Quantity / Cost`} accent style={{ marginTop: 20 }}>
              <p style={{ fontSize: 13, marginBottom: 4 }}>Rebar quantity: <b style={{ color: 'var(--val-pos)' }}>{detail.w_rebar.toFixed(3)} ton</b></p>
              <p style={{ fontSize: 13, marginBottom: 4 }}>Rebar cost: <b style={{ color: 'var(--val-pos)' }}>{detail.cost_rebar.toLocaleString()} ₩</b></p>
              <p style={{ fontSize: 13 }}>Concrete volume: <b style={{ color: 'var(--ac-main)' }}>{report.v_conc.toFixed(2)} m³</b></p>
              <p style={{ fontSize: 13 }}>Concrete cost: <b style={{ color: 'var(--ac-main)' }}>{report.cost_conc.toLocaleString()} ₩</b></p>
            </ResultBox>
          )}
        </>
      )}
    </div>
  )
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const labelStyle = { display: 'block', fontSize: 12, fontWeight: 500, color: 'var(--tx-secondary)', marginBottom: 4 }
const inputStyle = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 6, color: 'var(--tx-primary)', padding: '6px 10px', width: '100%', fontSize: 14 }
const th = { background: 'var(--bg-inset)', color: 'var(--ac-main)', fontWeight: 600, padding: '9px 12px', textAlign: 'left', borderBottom: '2px solid var(--bd-accent)' }
const td = { padding: '8px 12px', borderBottom: '1px solid var(--bd-subtle)', color: 'var(--tx-primary)' }
