/**
 * Structural Report — 슬래브 최소 배근 계획서
 * KDS 14 20 50 : 4.6.2
 */

export const SR_BARS = {
  D10: { a: 71.33,  w: 0.560 },
  D13: { a: 126.7,  w: 0.995 },
  D16: { a: 198.6,  w: 1.560 },
  D19: { a: 286.5,  w: 2.250 },
  D22: { a: 387.1,  w: 3.040 },
  D25: { a: 506.7,  w: 3.980 },
};

/**
 * @param {object} p
 * @param {number} p.h      슬래브 두께 (mm)
 * @param {number} p.fy     철근 항복강도 (MPa)
 * @param {number} p.area   시공 면적 (m²)
 * @param {number} p.pRebar 철근 단가 (₩/kg 또는 $/kg)
 * @param {number} p.pConc  콘크리트 단가 (₩/m³ 또는 $/m³)
 * @returns {object}
 */
export function calcStructReport({ h, fy, area = 0, pRebar = 0, pConc = 0 }) {
  // ρ_min — KDS 14 20 50 : 4.6.2
  let rho, rho_logic;
  if (fy <= 400) {
    rho = 0.0020;
    rho_logic = `fy (${fy} MPa) ≤ 400 MPa → ρ_min = 0.0020`;
  } else {
    const val = 0.0020 * (400 / fy);
    rho = Math.max(val, 0.0014);
    rho_logic = `ρ_min = 0.0020 × (400/${fy}) = ${val.toFixed(6)} ≥ 0.0014 → ρ_min = ${rho.toFixed(5)}`;
  }

  const as_req = rho * 1000 * h;                    // mm²/m
  const s_max  = Math.min(5 * h, 450);              // mm

  // 배근 스케줄
  const schedule = Object.entries(SR_BARS).map(([name, bar]) => {
    const s_single = Math.min(Math.floor((bar.a / as_req * 1000) / 10) * 10, s_max);
    const s_double = Math.min(Math.floor((bar.a / (as_req / 2) * 1000) / 10) * 10, s_max);
    return { name, area_mm2: bar.a, weight_kg_m: bar.w, s_single, s_double };
  });

  // 비용 계산 (선택)
  const v_conc = area * h / 1000; // m³
  const cost_conc = v_conc * pConc;

  return { rho, rho_logic, as_req, s_max, schedule, v_conc, cost_conc };
}

/**
 * 특정 배근 선택 시 물량/비용 계산
 * @param {string} barName
 * @param {number} spacing  간격 (mm)
 * @param {'Single'|'Double'} mode
 * @param {number} area     면적 (m²)
 * @param {number} pRebar   단가
 * @returns {object}
 */
export function calcRebarDetail(barName, spacing, mode, area, pRebar) {
  const bar = SR_BARS[barName];
  if (!bar) return null;
  const layers = mode === 'Single' ? 1 : 2;
  const w_rebar = ((1000 / spacing) * bar.w * layers * area * 2) / 1000; // ton
  return { w_rebar, cost_rebar: w_rebar * pRebar };
}
